#!/usr/bin/env python3
"""Patch 50: overview tile text tidied - one-line scenario, two-line outcome, one colour
throughout. Frontend only. Requires patch 49. Run from the repository root. Checked against the
exact files it was written for; nothing is written unless all of it matches. Safe to re-run."""
import hashlib, os, sys
def abort(msg):
    sys.exit(f"ABORT: {msg}. No files were written.")
REPLACE = {'frontend/src/Overview.jsx': {'before': '36da5bfb9fb5f76ed8fdf5902a9944a68f3564ea2a2148c98325b3e42bf266a2', 'after': 'import { useEffect, useState } from \'react\';\nimport { FAMILY_LABEL, FAMILY_SCENARIO } from \'./families\';\nimport OutcomeIcon from \'./OutcomeIcon\';\nimport \'./overview.css\';\n\n/**\n * Mission control: every case at a glance. Each tile\'s finding is produced by\n * the same rule as the Case Finding card (findingText.js) from the fields\n * /api/overview copies out of each case\'s artifacts - nothing is summarised or\n * written here. The family says what kind of test a case is, never which vessel\n * did it; the status dot is the system\'s own outcome.\n */\n/** What actually happened, in one sentence, from the case\'s result. */\nfunction happened(f, differs) {\n  if (!f) return \'Not yet analysed.\';\n  if (f.unknown_source) return \'No vessel named — no candidate fit the slick well enough.\';\n  const lead = f.best?.vessel_key;\n  return differs ? `Forward replay named ${lead}; the nearest vessel, ${f.nearest.vessel_key}, wasn’t supported.`\n    : `Forward replay named ${lead}, which was also the nearest vessel.`;\n}\n\nexport default function Overview({ api, onOpen, family = \'all\', chips = null }) {\n  const [rows, setRows] = useState(null);\n  const [error, setError] = useState(null);\n  useEffect(() => {\n    let live = true;\n    api.overview().then((r) => live && setRows(r)).catch((e) => live && setError(String(e.message ?? e)));\n    return () => { live = false; };\n  }, [api]);\n\n  if (error) return <div className="ov"><div className="error-banner">Failed to load the case overview: {error}</div></div>;\n  if (!rows) return <div className="ov"><div className="ov-loading">Loading cases…</div></div>;\n\n  const shown = family === \'all\' ? rows : rows.filter((r) => r.family === family);\n  const named = shown.filter((r) => r.finding && !r.finding.unknown_source).length;\n  const abstained = shown.filter((r) => r.finding?.unknown_source).length;\n  return (\n    <div className="ov">\n      <header className="ov-head">\n        <h1>All cases</h1>\n        <p>{shown.length === rows.length ? `${rows.length} cases` : `${shown.length} of ${rows.length} cases`} · {named} {named === 1 ? \'names\' : \'name\'} a vessel · {abstained} {abstained === 1 ? \'abstains\' : \'abstain\'}</p>\n      </header>\n      {chips}\n      <div className="ov-grid">\n        {shown.map((r, i) => {\n          const f = r.finding;\n          const unknown = f?.unknown_source;\n          const differs = f && !unknown && f.nearest && f.best && f.nearest.vessel_key !== f.best.vessel_key;\n          return (\n            <button type="button" key={r.incident_id} className={`ov-tile${unknown ? \' is-abstain\' : \'\'}`}\n                    style={{ \'--k\': i }} onClick={() => onOpen(r.incident_id)}>\n              <span className="ov-top">\n                {f && <OutcomeIcon abstain={unknown} />}\n                <span className="ov-id">{r.incident_id.replace(\'case_\', \'Case \')}</span>\n              </span>\n              {/* what the case is, then what actually happened - nothing else */}\n              <span className="ov-scenario">{FAMILY_SCENARIO[r.family] ?? FAMILY_LABEL[r.family] ?? \'\'}</span>\n              <span className="ov-happened">{happened(f, differs)}</span>\n              <span className="ov-open">Open case →</span>\n            </button>\n          );\n        })}\n      </div>\n      <p className="ov-foot">Findings are physical consistency under tested assumptions: investigative leads, not proof of\n        responsibility. Every case is synthetic.</p>\n    </div>\n  );\n}\n'}, 'frontend/src/overview.css': {'before': 'e5fbe01b8e03f9b586bdae1e5327a883bf404d3749bad488da94e77f7c2ee5bf', 'after': '/* Mission control: every case as a glass tile. */\n.ov { flex: 1; min-width: 0; height: 100%; overflow-y: auto; padding: var(--space-7) var(--space-7) var(--space-8); }\n.ov-head h1 { font-family: var(--font-display); font-size: 26px; font-weight: 700; letter-spacing: -0.02em; color: var(--label-1); }\n.ov-head p { margin: 4px 0 var(--space-6); font-size: var(--font-size-sm); color: var(--label-2); }\n.ov-loading { color: var(--label-2); font-size: var(--font-size-sm); }\n.ov-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(400px, 1fr)); gap: 16px; }\n.ov-tile {\n  position: relative; display: flex; flex-direction: column; gap: 10px; min-height: 176px; padding: 16px 16px 14px;\n  border: 0; border-radius: 14px; text-align: left; font: inherit; color: var(--label-1); cursor: default;\n  background: linear-gradient(160deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.015)), var(--surface-raised);\n  box-shadow: 0 0 0 0.5px var(--separator-strong), 0 6px 20px rgba(0, 0, 0, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.06);\n  --lift: 0px;\n  transform: perspective(900px) rotateX(var(--rx, 0deg)) rotateY(var(--ry, 0deg)) translateY(var(--lift));\n  animation: ov-in 480ms var(--ease-spring) backwards; animation-delay: calc(var(--k) * 45ms);\n  transition: transform 700ms cubic-bezier(0.22, 1.2, 0.36, 1), box-shadow var(--dur-base) ease;\n}\n.ov-tile.is-tilting { transition: transform 160ms ease-out, box-shadow var(--dur-base) ease; }\n.ov-tile::after { content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; opacity: 0;\n                  background: radial-gradient(360px circle at var(--mx, 50%) var(--my, 0%), rgba(var(--sheen-rgb), var(--sheen-max)), transparent 50%);\n                  transition: opacity 300ms ease; }\n.ov-tile.is-tilting::after { opacity: 1; }\n.ov-tile:hover { --lift: -3px; box-shadow: 0 0 0 0.5px rgba(10, 132, 255, 0.55), 0 14px 32px rgba(0, 0, 0, 0.2), 0 0 24px rgba(10, 132, 255, 0.12); }\n.ov-tile:active { --lift: 1px; }\n.ov-tile:focus-visible { outline: 3px solid var(--accent-ring); outline-offset: 2px; }\n.ov-tile.is-abstain { box-shadow: 0 0 0 0.5px rgba(255, 159, 10, 0.55), 0 6px 20px rgba(0, 0, 0, 0.12); }\n.ov-tile.is-abstain:hover { box-shadow: 0 0 0 0.5px rgba(255, 159, 10, 0.8), 0 14px 32px rgba(0, 0, 0, 0.2), 0 0 24px rgba(255, 159, 10, 0.14); }\n.ov-top { display: flex; align-items: center; gap: 8px; }\n.ov-dot { width: 9px; height: 9px; border-radius: 50%; background: var(--label-3); flex: none; }\n.ov-dot.is-named { background: var(--status-green); box-shadow: 0 0 8px rgba(48, 209, 88, 0.6); }\n.ov-dot.is-abstain { background: var(--status-orange); box-shadow: 0 0 8px rgba(255, 159, 10, 0.6); }\n.ov-id { font-family: var(--font-mono); font-size: var(--font-size-sm); font-weight: var(--font-weight-semibold); }\n.ov-family { margin-left: auto; padding: 2px 8px; border-radius: 999px; font-size: var(--font-size-xxs); color: var(--label-2);\n             background: var(--fill-pressed); white-space: nowrap; }\n.ov-finding { font-size: var(--font-size-sm); line-height: 1.45; color: var(--label-1); }\n.ov-finding.is-pending { color: var(--label-3); }\n.ov-facts { font-size: var(--font-size-xs); color: var(--label-2); }\n.ov-facts b { color: var(--label-1); font-weight: var(--font-weight-semibold); }\n.ov-facts .mono, .ov-facts b.mono { font-family: var(--font-mono); }\n.ov-open { margin-top: auto; font-size: var(--font-size-xs); font-weight: var(--font-weight-semibold); color: var(--accent);\n           opacity: 0; transform: translateX(-4px); transition: opacity var(--dur-base) ease, transform var(--dur-base) var(--ease-spring); }\n.ov-tile:hover .ov-open, .ov-tile:focus-visible .ov-open { opacity: 1; transform: none; }\n.ov-foot { margin-top: var(--space-6); font-size: var(--font-size-xs); color: var(--label-3); }\n@keyframes ov-in { from { opacity: 0; translate: 0 10px; } }\n@media (prefers-reduced-motion: reduce) { .ov-tile { animation: none; transform: none; } }\n\n/* the sidebar\'s way back to the overview */\n.nav-overview { display: flex; align-items: center; gap: 9px; width: 100%; margin: 0 0 10px; padding: 8px 12px;\n                border: 0; border-radius: 9px; background: transparent; color: var(--label-1); font: inherit;\n                font-size: var(--font-size-sm); font-weight: var(--font-weight-medium); cursor: default; text-align: left; }\n.nav-overview:hover { background: var(--fill-hover); }\n.nav-overview.is-active { background: var(--accent); color: var(--on-accent); }\n.nav-overview svg { width: 15px; height: 15px; flex: none; }\n\n/* what the case is: its scenario, and the facts of the scene */\n.ov-meta { font-size: var(--font-size-xs); color: var(--label-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }\n.ov-tile .ov-finding { color: var(--label-2); }\n\n/* tiles: the case, what it tests, and what happened */\n.ov-tile { min-height: 0; gap: 8px; padding: 16px 16px 18px; }\n.ov-top { gap: 9px; }\n.ov-top .sl-outcome, .ov-top .sl-outcome svg { width: 18px; height: 18px; }\n.ov-id { font-family: var(--font-display); font-size: var(--font-size-md); font-weight: var(--font-weight-semibold); letter-spacing: -0.01em; }\n/* the scenario stays one line, eased with an ellipsis if it ever runs long;\n   the outcome may take two - the same colour whatever it says */\n.ov-scenario { font-size: var(--font-size-sm); line-height: 1.45; color: var(--label-1); font-weight: var(--font-weight-medium);\n               white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.ov-happened { font-size: var(--font-size-sm); line-height: 1.45; color: var(--label-2); padding-bottom: 14px;\n               display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }\n.ov-open { position: absolute; right: 18px; bottom: 12px; margin: 0; }\n'}}
CL_OLD = 'the sidebar (one shared component). The sidebar drops its fit rings, and every count sits on one\nright edge.\n'
CL_NEW = 'the sidebar (one shared component). The sidebar drops its fit rings, and every count sits on one\nright edge.\n\n**Tile text tidied.** The scenario stays on one line (tiles widened so none truncate); the\noutcome sentence may wrap to two lines; and it is always the same colour, including for\nabstentions - an override that had picked it out in amber is removed. A leftover unused style\nrule from an earlier design pass is deleted.\n'
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 49 entry this appends after was not found - apply patch 49 first")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 50: {len(writes)} files written, {skipped} already in place.")
